/**
 * Typed client for the DeadEnd backend.
 *
 * Routes, query params and payload shapes are taken verbatim from
 * deadend_backend/openapi.json (generated by app/export_openapi.py from the
 * FastAPI app — not guessed). Paths used here:
 *
 *   POST /auth/device/start   { team_id?: str } -> { device_code, user_code,
 *        approve_url, interval, expires_in }
 *   GET  /auth/device/poll?device_code -> { status } | { status:"approved", token }
 *   POST /auth/device/resume  { device_code } -> { token, team_id }   (verified vs openapi.json: POST body, not GET query)
 *   GET  /auth/me (Bearer) -> { id, login, name, avatar_url, teams:[{team_id, role}] }
 *   POST /retrieve { team_id, error_text, env_fingerprint, task, include_global, budget_tokens }
 *        -> { signature_hash, results:[...], pack:[str], pack_tokens_est }
 *   POST /runs { team_id, task, repo_url?, agent } -> { run_id }
 *   POST /runs/{id}/events { phase, payload }
 *   POST /runs/{id}/finish?status=success|failure
 *   POST /runs/{id}/summary { agent, agent_version?, model?, tokens_in?, tokens_out?, duration?, context_used? }
 *   GET  /runs/{id}/stream  (SSE: data: {"seq","phase","payload"}, event: done data: {"status"})
 *   POST /reuse { entry_id, run_id?, outcome, kind, env_fingerprint }
 *   POST /promote { entry_id, team_id } -> { contribution_id, status, diff }
 *   POST /promote/approve { contribution_id } -> { published }
 *   GET  /entries?scope=private&team_id=&page=&per_page=&verified= -> [{page, per_page, entries:[...]}]
 *   GET  /stats/agents?team_id= -> { team_id, agents: { [agent]: {all, with_context, without_context} } }
 */
import * as http from "http";
import * as https from "https";
import { URL } from "url";

export const BACKEND_URL_DEFAULT = "https://deadend-4wyx.onrender.com";

export interface DeviceStartResp {
  device_code: string;
  user_code: string;
  approve_url: string;
  interval: number;
  expires_in: number;
}
export type DevicePollStatus = "pending" | "approved" | "denied" | "expired";
export interface MeResp {
  id: string;
  login: string;
  name?: string | null;
  avatar_url?: string | null;
  teams: { team_id: string; role: string }[];
}
export interface ConfidenceInfo {
  score?: number;
  observations?: number;
  verified?: boolean;
  [k: string]: unknown;
}
export interface RetrieveResult {
  entry_id: string;
  scope: "private" | "global";
  seeded?: boolean;
  verified?: boolean;
  signature?: string;
  error?: string;
  dead_ends: string[];
  constraints: string[];
  fix?: string | null;
  confidence: ConfidenceInfo;
}
export interface RetrieveResp {
  signature_hash: string;
  results: RetrieveResult[];
  pack: string[];
  pack_tokens_est: number;
}
export interface RunEventMsg {
  seq: number;
  phase: string;
  payload: Record<string, unknown>;
}
export interface EntryView {
  id: string;
  scope: string;
  team_id?: string | null;
  title?: string | null;
  signature_hash: string;
  signature_normalized?: string;
  redacted_error_text?: string;
  env_fingerprint?: Record<string, unknown>;
  attempts?: unknown[];
  fix?: Record<string, unknown> | null;
  constraints?: string[];
  seeded?: boolean;
  verified?: boolean;
  alpha?: number;
  beta?: number;
  created_at?: string;
}
export interface PromoteResp {
  contribution_id: string;
  status: string;
  diff?: Record<string, unknown>;
}
export type AgentStats = {
  runs: number; success_rate: number | null; avg_attempts: number | null;
  avg_tokens: number | null; max_tokens: number | null; avg_duration_s: number | null;
};
export interface SetupStatusResp {
  tokens_count: number;
  teams: { team_id: string; name: string; role: string }[];
  neatlogs_recorded: boolean | null;
  entire_recorded: boolean | null;
}

export class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(`(${status}) ${message}`);
  }
}

export class DeadEndApi {
  constructor(private baseUrl: string,
              private getToken: () => string | undefined | Promise<string | undefined>) {}

  private async headers(extra?: Record<string, string>): Promise<Record<string, string>> {
    const h: Record<string, string> = { "Content-Type": "application/json", ...extra };
    const tok = await this.getToken();
    if (tok) {
      h["Authorization"] = `Bearer ${tok}`;
    }
    return h;
  }

  /** Minimal node http(s) request without extra deps. */
  private request<T>(method: "GET" | "POST" | "DELETE", path: string,
                     body?: unknown, timeoutMs = 30000): Promise<T> {
    const url = new URL(path, this.baseUrl);
    return new Promise<T>(async (resolve, reject) => {
      const mod = url.protocol === "https:" ? https : http;
      const data = body === undefined ? undefined : JSON.stringify(body);
      const req = mod.request(url, {
        method,
        headers: await this.headers(data ? { "Content-Length": String(Buffer.byteLength(data)) } : {}),
        timeout: timeoutMs,
      }, (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () => {
          const text = Buffer.concat(chunks).toString("utf8");
          const status = res.statusCode || 0;
          if (status >= 400) {
            reject(new ApiError(status, text.slice(0, 300)));
            return;
          }
          try {
            resolve(text ? (JSON.parse(text) as T) : ({} as T));
          } catch {
            reject(new ApiError(status, `bad JSON from ${path}`));
          }
        });
      });
      req.on("timeout", () => req.destroy(new ApiError(0, `${path} timed out`)));
      req.on("error", reject);
      if (data) {
        req.write(data);
      }
      req.end();
    });
  }

  // ------------------------------------------------------------- device flow
  deviceStart(teamId?: string): Promise<DeviceStartResp> {
    const q = teamId ? `?team_id=${encodeURIComponent(teamId)}` : "";
    return this.request("POST", `/auth/device/start${q}`, {});
  }

  devicePoll(deviceCode: string): Promise<{ status: DevicePollStatus; token?: string }> {
    return this.request("GET", `/auth/device/poll?device_code=${encodeURIComponent(deviceCode)}`);
  }

  /** Token is delivered exactly once, after approval. openapi.json says
   * POST with a JSON body. */
  deviceResume(deviceCode: string): Promise<{ token: string; team_id?: string }> {
    return this.request("POST", "/auth/device/resume", { device_code: deviceCode });
  }

  me(): Promise<MeResp> {
    return this.request("GET", "/auth/me");
  }

  // ----------------------------------------------------------------- context
  retrieve(body: {
    team_id: string; error_text: string; env_fingerprint?: Record<string, unknown>;
    task?: string; include_global?: boolean; budget_tokens?: number;
  }): Promise<RetrieveResp> {
    return this.request("POST", "/retrieve", {
      include_global: true, budget_tokens: 1500, env_fingerprint: {}, task: "", ...body,
    });
  }

  // -------------------------------------------------------------------- runs
  createRun(body: { team_id: string; task: string; repo_url?: string; agent: string }): Promise<{ run_id: string }> {
    return this.request("POST", "/runs", body);
  }

  runEvent(runId: string, phase: string, payload: Record<string, unknown>): Promise<{ seq: number }> {
    return this.request("POST", `/runs/${encodeURIComponent(runId)}/events`, { phase, payload });
  }

  finishRun(runId: string, status: "success" | "failure"): Promise<unknown> {
    return this.request("POST", `/runs/${encodeURIComponent(runId)}/finish?status=${status}`, {});
  }

  summarizeRun(runId: string, body: {
    agent: string; agent_version?: string | null; model?: string | null;
    tokens_in?: number | null; tokens_out?: number | null; duration?: number | null;
    context_used?: boolean;
  }): Promise<unknown> {
    return this.request("POST", `/runs/${encodeURIComponent(runId)}/summary`, body);
  }

  // ------------------------------------------------------------------- reuse
  reuse(body: {
    entry_id: string; run_id?: string; outcome: "success" | "failure";
    kind?: "real" | "test"; env_fingerprint?: Record<string, unknown>;
  }): Promise<unknown> {
    return this.request("POST", "/reuse", { kind: "real", env_fingerprint: {}, ...body });
  }

  // --------------------------------------------------------------- promotion
  promote(body: { entry_id: string; team_id: string }): Promise<PromoteResp> {
    return this.request("POST", "/promote", body);
  }

  promoteApprove(body: { contribution_id: string }): Promise<{ published: boolean }> {
    return this.request("POST", "/promote/approve", body);
  }

  // ----------------------------------------------------------------- entries
  listEntries(scope: "private" | "global", opts?: {
    team_id?: string; page?: number; per_page?: number; verified?: boolean;
  }): Promise<EntryView[]> {
    const q = new URLSearchParams({ scope, ...(opts?.team_id ? { team_id: opts.team_id } : {}),
      page: String(opts?.page ?? 1), per_page: String(opts?.per_page ?? 20) });
    if (opts?.verified !== undefined) {
      q.set("verified", String(opts.verified));
    }
    // GET /entries returns a one-element wrapper array: [{page, per_page, entries}]
    return this.request<[{ page: number; per_page: number; entries: EntryView[] }]>(
      "GET", `/entries?${q.toString()}`).then((r) => (r[0]?.entries ?? []));
  }

  // ------------------------------------------------------------------- stats
  statsAgents(teamId: string): Promise<{
    team_id: string;
    agents: Record<string, {
      all: { runs: number; success_rate: number | null; avg_tokens: number | null; avg_duration_s: number | null };
      with_context: AgentStats; without_context: AgentStats;
    }>;
  }> {
    return this.request("GET", `/stats/agents?team_id=${encodeURIComponent(teamId)}`);
  }

  /** GET /entries/{id} — full entry incl. reuse counts + confidence. */
  requestEntry(entryId: string): Promise<EntryView & {
    observations?: number; reuse_success?: number;
    confidence?: { score?: number; observations?: number };
  }> {
    return this.request("GET", `/entries/${encodeURIComponent(entryId)}`);
  }

  // -------------------------------------------------------------- setup facts
  /**
   * GET /me/setup-status — real per-user facts for the setup checklist:
   * { tokens_count: number,
   *   teams: [{team_id, name, role}],
   *   neatlogs_recorded: boolean | null,
   *   entire_recorded: boolean | null }
   * null means "no record event yet", NOT false.
   */
  setupStatus(): Promise<SetupStatusResp> {
    return this.request("GET", "/me/setup-status");
  }

  // -------------------------------------------------------------------- SSE
  /**
   * Follow GET /runs/{id}/stream (SSE). Parses `data: {...}` lines and the
   * `event: done` block per the router's StreamingResponse format.
   */
  runStream(runId: string, onEvent: (ev: RunEventMsg) => void,
            onDone: (status: string) => void, onAbort: (fn: () => void) => void,
            token: string): void {
    const url = new URL(`/runs/${encodeURIComponent(runId)}/stream`, this.baseUrl);
    const mod = url.protocol === "https:" ? https : http;
    const req = mod.request(url, {
      method: "GET",
      headers: { Authorization: `Bearer ${token}`, Accept: "text/event-stream" },
    }, (res) => {
      let buf = "";
      let eventName = "message";
      res.setEncoding("utf8");
      res.on("data", (chunk: string) => {
        buf += chunk;
        let idx: number;
        while ((idx = buf.indexOf("\n")) >= 0) {
          const line = buf.slice(0, idx).replace(/\r$/, "");
          buf = buf.slice(idx + 1);
          if (line.startsWith("event:")) {
            eventName = line.slice(6).trim();
          } else if (line.startsWith("data:")) {
            const data = line.slice(5).trim();
            let obj: Record<string, unknown> = {};
            try {
              obj = JSON.parse(data);
            } catch {
              obj = {};
            }
            if (eventName === "done") {
              onDone(String(obj.status ?? ""));
              eventName = "message";
            } else if (typeof obj.seq === "number") {
              onEvent(obj as unknown as RunEventMsg);
            }
          } else if (line === "") {
            eventName = "message";
          }
        }
      });
      res.on("error", () => { /* stream closed */ });
    });
    req.on("error", () => { /* backend restart etc. */ });
    req.end();
    onAbort(() => req.destroy());
  }
}
